mapper.select:
SELECT t.id, t.visitor_name, t.visitor_phone, t.visitor_id_card, t.vendor_factory, t.vendor_region, t.visited_name, t.visited_phone, t.vendor_matter, t.start_time, t.end_time, t.vendor_unit, t.card_no, t.photo, t.vendor_state, t.hairpin_no, t.recovery_no, t.create_time, t.update_time, t.delete_falg, t.eip_flow_id, t.secret_state, t.secret_region, t.hairpin_time, t.recovery_time, t.factory_id, t.region_id, t.wx_phone, t.qr_code, NOW() as now_time, t.visited_dept, t.eip_create_time, t.user_id,t.act_in_factory,t.in_factory_process,t.issue_factory,t.un_issue_factory, t.authorized_no, t.authorized_name, t.authorized_by_no, t.authorized_by_name, t.id_card_photo FROM safety_visitor_hairpin t WHERE t.delete_falg = 0 and t.end_time >= NOW() and t.vendor_state <> 7
AND (${authFactory})
ORDER BY t.create_time desc limit #{startRowNum},#{endRowNum}

  select id,act_in_factory, visitor_phone, visitor_id_card, id_card_photo from safety_visitor_hairpin
  where
    visitor_phone = #{visitorPhone}

    and start_time <= #{startTime}
    and end_time >= #{endTime}

    and vendor_state in (1,11,8,9)
and factory_id like concat('%',#{factoryId},'%')

select v.id,v.visited_name,v.vendor_unit,v.visitor_name,v.start_time,v.end_time,m.emp_no
from safety_visitor_hairpin v
left join safety_employee_message m on v.visited_phone = m.phone_no
where
  v.visitor_phone = #{visitorPhone}

  and v.start_time <= #{startTime}
  and v.end_time >= #{endTime}

      and v.vendor_state in (1,11,8,9)
  and v.factory_id like concat('%',#{factoryId},'%')

select v.id,v.visited_name,v.vendor_unit,v.visitor_name,v.start_time,v.end_time,m.emp_no
from safety_visitor_hairpin v
left join safety_employee_message m on v.visited_phone = m.phone_no
where
  v.visitor_phone = #{visitorPhone}

  and v.start_time <= #{startTime}
  and v.end_time >= #{endTime}
  and v.vendor_state is not null
  and v.vendor_state <> 3

  and v.factory_id like concat('%',#{factoryId},'%')
